UPDATE pcd_payment_callback_log_table
SET callback_status = #{callbackStatus}, error_message = #{errorMessage}
WHERE id = #{id}

UPDATE pcd_payment_callback_log_table
SET retry_count = retry_count + 1, callback_status = 'RETRYING'
WHERE id = #{id}

mapper.select:
SELECT * FROM pcd_payment_callback_log_table
WHERE callback_status = 'FAILED' AND retry_count < 5
ORDER BY created_at ASC LIMIT #{limit}
